function followPlayer(dt,snap=false){
  if(!human||!camera)return;
  const p=human.group.position,a=-Math.PI/2+human.team*Math.PI*2/5,fx=-Math.cos(a),fz=-Math.sin(a);
  // Keep the camera behind this team's lane so its towers stay in front of the player.
  const portrait=camera.aspect<1,h=portrait?21:16,z=portrait?17:13;
  const target=new THREE.Vector3(p.x-fx*z,p.y+h,p.z-fz*z);
  if(snap)camera.position.copy(target);
  else camera.position.lerp(target,1-Math.exp(-12*dt));
  camera.lookAt(p.x+fx*8,p.y+1.1,p.z+fz*8);
}
