async function refreshQuizScores(){if(quizScoreBusy)return;const status=$('scoreStatus');if(!arenaSession){if(status)status.textContent='Demo: markah kuiz hanya ada dalam sesi Arena sebenar.';renderScoreboard();return;}if(status)status.textContent='Sedang memuat markah kuiz…';quizScoreBusy=true;try{const result=await window.call('leaderboard',arenaSession);if(!Array.isArray(result)||!result.length){quizScoresReady=false;if(status)status.textContent='Markah kuiz belum tersedia. Cuba lagi selepas guru tamatkan sesi kuiz.';renderScoreboard();return;}const byNick=new Map(),ambiguous=new Set();for(const p of result){const nick=normalizeArenaNick(p.name),points=Number(p.points??p.score);if(!nick||!Number.isFinite(points))continue;if(byNick.has(nick))ambiguous.add(nick);else byNick.set(nick,points);}for(const nick of ambiguous)byNick.delete(nick);quizScoreByNick=byNick;quizScoresReady=true;if(status)status.textContent=`Markah kuiz diterima untuk ${byNick.size}/${result.length} nama unik. Nama panggilan 6 aksara yang bertindih tidak dipadankan.`;renderScoreboard();}catch(error){if(status)status.textContent=`Markah kuiz belum dapat dimuatkan: ${error.message||'cuba semula'}`;}finally{quizScoreBusy=false;}}
