function minionStep(dt){for(const m of minions){if(!m.guardTower||!m.group)continue;const base=bases[m.team];if(base?.eliminated){m.alive=false;m.group.visible=false;continue;}if(!m.alive){m.respawn-=dt;if(m.respawn<=0){m.alive=true;m.hp=m.maxHp;m.group.visible=true;m.group.position.set(m.homeX,.1,m.homeZ);drawHealthBar(m);}continue;}const enemy=nearestGuardThreat(m);let targetX=m.homeX,targetZ=m.homeZ;if(enemy){targetX=enemy.group.position.x;targetZ=enemy.group.position.z;}const dx=targetX-m.group.position.x,dz=targetZ-m.group.position.z,d=Math.hypot(dx,dz);if(enemy&&d<=1.55){m.group.rotation.y=Math.atan2(dx,dz);if(elapsed>=m.attackAt){m.attackAt=elapsed+1.5;damageUnit(enemy,4,m);createElementEffect(enemy.group.position.x,.8,enemy.group.position.z,heroes[m.hero].element,.48);}continue;}const stop=enemy?1.25:.75;if(d>stop){const speed=enemy?2.7:2.2,moved=moveArenaUnit(m.group.position,dx/d*dt*speed,dz/d*dt*speed,.28,m.team);m.group.position.x=moved.x;m.group.position.z=moved.z;m.group.rotation.y=Math.atan2(dx,dz);}}}
