function finishGame(alive){gameOver=true;cancelAnimationFrame(raf);const ranked=[...bases].sort((a,b)=>Number(b.eliminated)-Number(a.eliminated)||towerHp(b)-towerHp(a));$('winnerTitle').textContent=`🏆 Pasukan ${teams[(alive[0]||ranked[ranked.length-1]).team].name} menang!`;$('finalTeams').innerHTML=ranked.map((b,i)=>`<div class="final-team"><b style="color:${teams[b.team].css}">${b.eliminated?'Tersingkir':`#${ranked.length-i} ${teams[b.team].name}`}</b><span>${b.eliminated?'CORE musnah':`CORE berdiri · ${Math.round(towerHp(b))} HP`}</span></div>`).join('');$('endModal').classList.remove('hidden');renderScoreboard();if(arenaSession)refreshQuizScores();}
function resetGame(){if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});setArenaFullscreenFallback(false);for(const u of units)scene?.remove(u.group);for(const m of minions)scene?.remove(m.group);const guardGeometries=new Set();for(const batch of guardRenderBatches)for(const mesh of batch.meshes){scene?.remove(mesh);guardGeometries.add(mesh.geometry);}for(const geometry of guardGeometries)geometry.dispose();guardRenderBatches=[];units=[];minions=[];bases.forEach(b=>{b.objects.forEach(o=>scene?.remove(o));b.towers.forEach(t=>scene?.remove(t.group));});bases=[];jungleCamps=[];for(const o of world)scene?.remove(o);world=[];for(const fx of effects)scene?.remove(fx.mesh);effects=[];if(renderer){renderer.dispose();renderer.forceContextLoss();renderer=null;scene=null;camera=null;}human=null;skillReady=[0,0,0,0,0];attackReady=0;questionIndex=-1;$('battle').classList.add('hidden');$('endModal').classList.add('hidden');$('questionModal').classList.add('hidden');$('setup').classList.remove('hidden');startHeroPreview();}
$('startBtn').onclick=startGame;$('attackBtn').onclick=hit;document.querySelectorAll('.skill-btn').forEach(b=>b.onclick=()=>openSkill(Number(b.dataset.skill)));$('againBtn').onclick=resetGame;
function toggleScorePanel(){const panel=$('scorePanel'),btn=$('scoreToggleBtn'),open=panel.hidden;panel.hidden=!open;btn.setAttribute('aria-expanded',String(open));renderScoreboard();if(open)refreshQuizScores();}
$('scoreToggleBtn').addEventListener('click',toggleScorePanel);$('refreshScoresBtn').addEventListener('click',refreshQuizScores);$('refreshFinalScores').addEventListener('click',refreshQuizScores);$('fullScreenBtn').addEventListener('click',toggleArenaFullscreen);document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&document.body.classList.contains('arena-fs-fallback'))setArenaFullscreenFallback(false);updateFullscreenControl();});updateFullscreenControl();
const joyPad=$('joystick'),knob=$('knob');let pointer=null;function joyMove(e){if(pointer!==e.pointerId)return;const r=joyPad.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.34,len=Math.hypot(dx,dy),s=len>max?max/len:1;joy.x=clamp(dx*s/max,-1,1);joy.y=clamp(dy*s/max,-1,1);knob.style.transform=`translate(${joy.x*max}px,${joy.y*max}px)`;}joyPad.addEventListener('pointerdown',e=>{pointer=e.pointerId;joyPad.setPointerCapture(pointer);joyMove(e);});joyPad.addEventListener('pointermove',joyMove);function joyEnd(){pointer=null;joy={x:0,y:0};knob.style.transform='translate(0,0)';}joyPad.addEventListener('pointerup',joyEnd);joyPad.addEventListener('pointercancel',joyEnd);
